<script setup lang="ts">
import { ref, watch } from 'vue';
import { api } from '../platform';
import { type Row, formatTime } from '../../../shared/domain';
import { useBroadcastManager, broadcastStates } from '../../../shared/useBroadcasts';
import ForumAudioFieldMobile from './ForumAudioFieldMobile.vue';
import ForumAudioMobile from './ForumAudioMobile.vue';
const props = defineProps<{ user: Row | null }>();const emit = defineEmits<{ (event: 'updated'): void }>();
const { allowed, rows, form, withdrawing, error, message, busy, loading, load, edit, save, withdraw } = useBroadcastManager(() => props.user, api, () => emit('updated'));
const uploading = ref(false);watch(form, () => { uploading.value = false; });
</script>
<template><view v-if="allowed"><view class="title">全站广播</view><view class="intro">文字与语音通知，向所有访问者展示。</view><view class="button-row"><button class="primary" :disabled="busy || uploading" @click="edit()">新建广播</button><button class="outline" :disabled="busy || uploading" @click="load">刷新广播</button></view><view v-if="error" class="error">{{ error }}</view><view v-if="message" class="notice-line">{{ message }}</view>
<view v-if="form" class="panel broadcast-form"><view class="section-title">{{ form.id ? '编辑广播' : '新建广播' }}</view><view class="field"><text class="field-label">广播标题</text><input v-model="form.title" :disabled="busy || uploading" maxlength="60" placeholder="填写广播标题"/></view><view class="field"><text class="field-label">广播文字</text><textarea v-model="form.content" :disabled="busy || uploading" maxlength="1000" placeholder="填写文字内容，也可作为语音文字说明"/></view><view class="field"><text class="field-label">生效时间（北京时间，留空立即）</text><input v-model="form.startsAt" :disabled="busy || uploading" placeholder="例如 2026-11-04 09:00"/></view><view class="field"><text class="field-label">到期时间（北京时间）</text><input v-model="form.endsAt" :disabled="busy || uploading" placeholder="例如 2026-11-05 18:00"/></view><ForumAudioFieldMobile :key="form.id || form.requestId" v-model="form.audio" :user-id="user?.id" scope="broadcast" :disabled="busy" @busy="uploading = $event"/><ForumAudioMobile v-if="form.audio" :key="form.audio.id" :attachment="form.audio"/><view class="button-row"><button class="primary" :disabled="busy || uploading" @click="save('published')">发布广播</button><button class="outline" :disabled="busy || uploading" @click="save('draft')">保存草稿</button><button class="text-button" :disabled="busy || uploading" @click="form = null">取消编辑</button></view><view class="safe-note">发布后全站最长约30秒更新，语音由访问者主动播放。文字内容为必填。</view></view>
<view v-if="withdrawing" class="panel"><view>确认撤下“{{ withdrawing.title }}”？</view><view class="button-row"><button class="primary" :disabled="busy" @click="withdraw">确认撤下</button><button class="outline" :disabled="busy" @click="withdrawing = null">返回</button></view></view><view v-if="loading" class="safe-note">正在加载广播…</view><view v-else-if="!rows.length && !error" class="empty">还没有广播，点击“新建广播”添加。</view><view v-for="row in rows" :key="row.id" class="panel broadcast-record"><text class="tag">{{ broadcastStates[row.state] }}</text><view class="card-title">{{ row.title }}</view><view class="broadcast-text">{{ row.content }}</view><view class="meta">{{ formatTime(row.startsAt) }} — {{ formatTime(row.endsAt) }} · 北京时间{{ row.audio ? ' · 含语音' : '' }}</view><view class="button-row"><button class="outline" :disabled="busy || uploading" @click="edit(row)">编辑</button><button v-if="['active','scheduled'].includes(row.state)" class="outline" :disabled="busy || uploading" @click="withdrawing = row">撤下</button></view></view></view></template>
<style scoped>.broadcast-form textarea{width:100%;height:220rpx}.broadcast-form .field{margin:28rpx 0}.broadcast-text{white-space:pre-wrap;word-break:break-all;font-size:28rpx;line-height:1.8;margin:22rpx 0;max-height:300rpx;overflow:auto}.broadcast-record .card-title{margin-top:18rpx}.button-row{display:flex;flex-wrap:wrap;gap:14rpx;margin:20rpx 0}.button-row button{min-height:44px}</style>
